const cfg = $('Set - Zombie Hunt Config').first().json;
const sitemapResp = $input.first().json;

let urls = [];
const xml = sitemapResp.data || sitemapResp.body || (typeof sitemapResp === 'string' ? sitemapResp : '');
if (typeof xml === 'string' && xml.includes('<loc>')) {
  urls = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map(m => m[1].trim());
}
if (urls.length === 0) urls = [cfg.siteUrl];

if (cfg.sameDomainOnly) {
  let seedHost = '';
  try { seedHost = new URL(cfg.siteUrl).hostname; } catch (e) {}
  urls = urls.filter(u => { try { return new URL(u).hostname === seedHost; } catch (e) { return false; } });
}

urls = [...new Set(urls)].slice(0, Number(cfg.maxPages) || 200);

return urls.map(u => ({ json: { ...cfg, pageUrl: u } }));

const cfg = $('Loop Over Pages (Crawl)').first().json;
const extracted = $input.first().json;
const pageUrl = cfg.pageUrl;

function toAbsolute(href, base) { try { return new URL(href, base).toString(); } catch (e) { return null; } }
let seedHost = '';
try { seedHost = new URL(cfg.siteUrl).hostname; } catch (e) {}

const hrefs = extracted.linkHrefs || [];
const links = hrefs.map(href => {
  const abs = toAbsolute(href, pageUrl);
  if (!abs) return null;
  let isInternal = false;
  try { isInternal = new URL(abs).hostname === seedHost; } catch (e) {}
  return { targetUrl: abs, isInternal };
}).filter(Boolean);

const bodyText = (extracted.bodyText || '').replace(/\s+/g, ' ').trim();
const wordCount = bodyText ? bodyText.split(' ').length : 0;
const robotsMeta = (extracted.robotsMeta || '').toLowerCase();
const hasNoindexTag = robotsMeta.includes('noindex');

let canonicalUrl = null;
try { canonicalUrl = extracted.canonicalHref ? new URL(extracted.canonicalHref, pageUrl).toString() : null; } catch (e) {}
const canonicalMismatch = !!(canonicalUrl && canonicalUrl !== pageUrl);

return [{
  json: {
    ...cfg,
    title: (extracted.title || '').trim(),
    metaDescription: (extracted.metaDescription || '').trim(),
    wordCount,
    isThinContent: wordCount < Number(cfg.minWordCount || 300),
    hasNoindexTag,
    canonicalUrl,
    canonicalMismatch,
    outboundLinks: links,
    crawledAt: new Date().toISOString()
  }
}];

