INSERT INTO zombie_page_links (source_url, target_url, is_internal)
VALUES ($1, $2, true)
ON CONFLICT (source_url, target_url) DO NOTHING;

UPDATE zombie_page_crawl SET inbound_internal_links = 0;
UPDATE zombie_page_crawl c SET inbound_internal_links = sub.cnt
FROM (SELECT target_url, COUNT(DISTINCT source_url) AS cnt FROM zombie_page_links WHERE is_internal = true GROUP BY target_url) sub
WHERE c.page_url = sub.target_url;

