const d = $input.first().json;
let pagePath = '/';
try { pagePath = new URL(d.pageUrl).pathname || '/'; } catch (e) {}

const end = new Date();
const start = new Date(end.getTime() - Number(d.trafficLookbackDays || 90) * 24 * 60 * 60 * 1000);
const fmt = dt => dt.toISOString().slice(0, 10);

return [{ json: { ...d, pagePath, dateRangeStart: fmt(start), dateRangeEnd: fmt(end) } }];

const d = $('JS - Prepare Page Signals Context').first().json;
const resp = $input.first().json;

const row = (resp.rows || [])[0];
const mv = row ? row.metricValues.map(m => Number(m.value)) : [0, 0, 0, 0];

return [{
  json: {
    ...d,
    ga4: { pageviews: mv[0] || 0, sessions: mv[1] || 0, engagementRate: mv[2] || 0, avgSessionDurationSec: mv[3] || 0 }
  }
}];

const d = $('JS - Prepare Page Signals Context').first().json;
const resp = $input.first().json;

const row = (resp.rows || [])[0] || {};
return [{
  json: {
    ...d,
    gsc: { clicks: row.clicks || 0, impressions: row.impressions || 0, ctr: row.ctr || 0, avgPosition: row.position || null }
  }
}];

const d = $('JS - Prepare Page Signals Context').first().json;
const resp = $input.first().json;

const verdictResult = (resp.inspectionResult || {}).indexStatusResult || {};
const isIndexed = verdictResult.verdict === 'PASS' || (verdictResult.coverageState || '').toLowerCase().includes('indexed');

return [{
  json: {
    ...d,
    indexation: { isIndexed, coverageState: verdictResult.coverageState || 'UNKNOWN', verdict: verdictResult.verdict || 'UNKNOWN' }
  }
}];

// ---- PLACEHOLDER PARSING — adjust field names to match your real backlink provider's response ----
const d = $('JS - Prepare Page Signals Context').first().json;
const resp = $input.first().json;

const referringDomains = Number(resp.referringDomains ?? resp.referring_domains ?? 0) || 0;
const totalBacklinks = Number(resp.totalBacklinks ?? resp.backlinks ?? 0) || 0;

return [{ json: { ...d, backlinks: { referringDomains, totalBacklinks } } }];

const d = $('JS - Parse Backlink Metrics').first().json;
const crawl = ($input.first().json) || {};

const wordCount = crawl.word_count ?? 0;
const isThinContent = crawl.is_thin_content ?? (wordCount < Number(d.minWordCount || 300));
const hasNoindex = crawl.has_noindex ?? false;
const inboundInternalLinks = crawl.inbound_internal_links ?? 0;

const ga4 = d.ga4 || { pageviews: 0, sessions: 0 };
const gsc = d.gsc || { clicks: 0, impressions: 0 };
const backlinks = d.backlinks || { referringDomains: 0, totalBacklinks: 0 };
const indexation = d.indexation || { isIndexed: false, coverageState: 'UNKNOWN' };

function tier(value, thresholds, points) {
  for (let i = 0; i < thresholds.length; i++) if (value < thresholds[i]) return points[i];
  return points[points.length - 1];
}

// Each block's points represent how "zombie-like" that signal is (higher = worse).
const trafficPoints   = tier(ga4.sessions,        [1, 5, 20],  [35, 25, 12, 0]);
const searchPoints    = tier(gsc.impressions,     [1, 10, 50], [25, 18, 8, 0]);
const backlinkPoints  = tier(backlinks.referringDomains, [1, 3], [15, 8, 0]);
const contentPoints   = hasNoindex ? 15 : (isThinContent ? 10 : 0);
const internalPoints  = tier(inboundInternalLinks, [1, 3], [10, 5, 0]);

const zombieScore = Math.min(100, trafficPoints + searchPoints + backlinkPoints + contentPoints + internalPoints);

const zombieThreshold = Number(d.zombieThreshold || 70);
const atRiskThreshold = Number(d.atRiskThreshold || 40);
const status = zombieScore >= zombieThreshold ? 'zombie' : (zombieScore >= atRiskThreshold ? 'at_risk' : 'healthy');

const reasons = [];
if (trafficPoints > 0) reasons.push('low/no GA4 sessions (' + ga4.sessions + ')');
if (searchPoints > 0) reasons.push('low/no GSC impressions (' + gsc.impressions + ')');
if (backlinkPoints > 0) reasons.push('few/no referring domains (' + backlinks.referringDomains + ')');
if (contentPoints > 0) reasons.push(hasNoindex ? 'page is noindexed' : 'thin content (' + wordCount + ' words)');
if (internalPoints > 0) reasons.push('few/no inbound internal links (' + inboundInternalLinks + ')');

// Deterministic, auditable recommendation — kept independent of the optional Claude rationale below.
let recommendedAction = 'keep';
if (hasNoindex && ga4.sessions === 0 && gsc.impressions === 0) {
  recommendedAction = 'leave_as_is_intentional_noindex';
} else if (status === 'zombie' && backlinks.referringDomains > 0) {
  recommendedAction = 'consolidate_or_redirect_preserve_link_equity';
} else if (status === 'zombie') {
  recommendedAction = 'delete_or_redirect';
} else if (status === 'at_risk') {
  recommendedAction = 'improve_content_and_internal_links';
}

return [{
  json: {
    pageUrl: d.pageUrl, title: d.title,
    ga4, gsc, backlinks, indexation,
    wordCount, isThinContent, hasNoindex, inboundInternalLinks,
    zombieScore, status, reasons, recommendedAction,
    slackChannel: d.slackChannel, anthropicModel: d.anthropicModel
  }
}];

const d = $('IF - Needs Recommendation?').first().json;
const resp = $input.first().json;

const textBlock = (resp.content || []).find(b => b.type === 'text');
let ai;
try { ai = JSON.parse((textBlock?.text || '{}').replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; }

return [{ json: { ...d, aiRationale: ai.rationale || '', aiSuggestedNextStep: ai.suggestedNextStep || '' } }];

